@import url('https://fonts.googleapis.com/css2?family=Inter:wght@200;300;400;500;600;700;800&display=swap');

:root{
  --dgs-pink:#ea3f8b;
  --dgs-orange:#ffae33;
  --dgs-blue:#72c1d8;
  --dgs-purple:#634dbc;
  --dgs-white:#fff;
  --dgs-muted:rgba(255,255,255,.70);
  --dgs-soft:rgba(255,255,255,.52);
  --dgs-line:rgba(255,255,255,.11);
  --dgs-card:rgba(255,255,255,.04);
  --dgs-grad:linear-gradient(90deg,#ea3f8b,#ffae33,#72c1d8,#634dbc);
}

html{scroll-behavior:smooth!important;}
body{margin:0!important;padding:0!important;background:#000!important;overflow-x:hidden!important;}
#global-webgl-background{z-index:0!important;background:#000!important;}
#global-webgl-background canvas{display:block;position:fixed;top:0;left:0;}

.dgs-ai-page,.dgs-ai-page *{box-sizing:border-box!important;}
.dgs-ai-page{
  width:100vw!important;
  max-width:none!important;
  margin-left:calc(50% - 50vw)!important;
  margin-right:calc(50% - 50vw)!important;
  position:relative!important;
  z-index:1!important;
  background:transparent!important;
  color:#fff!important;
  font-family:'Inter',sans-serif!important;
  line-height:1.65!important;
  overflow:hidden!important;
}
.dgs-ai-page section{position:relative;z-index:1;background:transparent!important;}
.dgs-ai-page a{text-decoration:none!important;color:inherit!important;}
.dgs-ai-page img{max-width:100%;display:block;}

.dgs-wrap{width:100%!important;max-width:none!important;margin:0 auto!important;padding-left:clamp(20px,4vw,72px)!important;padding-right:clamp(20px,4vw,72px)!important;position:relative;z-index:2;}
.dgs-narrow{max-width:920px;}
.dgs-center{text-align:center;margin-left:auto;margin-right:auto;}
.dgs-section{padding:clamp(82px,11vw,170px) 0;background:transparent!important;}
.dgs-section-tight{padding:clamp(62px,8vw,116px) 0;background:transparent!important;}
.dgs-grid{display:grid;gap:clamp(18px,2vw,30px);}

.dgs-eyebrow{
  font-size:clamp(.68rem,1.3vw,.78rem)!important;
  font-weight:400!important;
  letter-spacing:clamp(2px,.45vw,4px)!important;
  text-transform:uppercase!important;
  color:rgba(255,255,255,.56)!important;
  margin:0 0 20px!important;
}
.dgs-grad-text{
  background:var(--dgs-grad)!important;
  background-size:220% 100%!important;
  -webkit-background-clip:text!important;
  background-clip:text!important;
  -webkit-text-fill-color:transparent!important;
  color:transparent!important;
  animation:dgsGradient 9s ease infinite!important;
}
.dgs-title-small{
  font-size:clamp(2rem,4.6vw,4.2rem)!important;
  font-weight:230!important;
  letter-spacing:-.04em!important;
  line-height:1.08!important;
  color:#fff!important;
  margin:0!important;
}
.dgs-copy{
  font-size:clamp(.98rem,1.7vw,1.15rem)!important;
  font-weight:300!important;
  color:var(--dgs-muted)!important;
  line-height:1.85!important;
  margin:0!important;
}

@keyframes dgsGradient{0%,100%{background-position:0% 50%;}50%{background-position:100% 50%;}}
@keyframes dgsFloat{0%,100%{transform:translateY(0);}50%{transform:translateY(-10px);}}
@keyframes dgsDrop{0%{transform:translateY(0);opacity:0;}50%{opacity:1;}100%{transform:translateY(60px);opacity:0;}}

.dgs-btn-row{display:flex;flex-wrap:wrap;gap:14px;align-items:center;}
.dgs-btn{
  display:inline-flex!important;
  align-items:center!important;
  justify-content:center!important;
  gap:10px!important;
  min-height:54px!important;
  padding:16px 28px!important;
  border-radius:999px!important;
  font-family:'Inter',sans-serif!important;
  font-weight:500!important;
  font-size:.95rem!important;
  letter-spacing:.2px!important;
  transition:.3s ease!important;
  cursor:pointer!important;
}
.dgs-btn-primary{background:linear-gradient(135deg,var(--dgs-pink),var(--dgs-orange))!important;color:#fff!important;box-shadow:0 14px 42px rgba(234,63,139,.35)!important;}
.dgs-btn-primary:hover{transform:translateY(-4px) scale(1.018)!important;box-shadow:0 22px 62px rgba(234,63,139,.48)!important;}
.dgs-btn-ghost{border:1px solid rgba(255,255,255,.16)!important;background:rgba(255,255,255,.045)!important;color:#fff!important;backdrop-filter:blur(12px)!important;}
.dgs-btn-ghost:hover{transform:translateY(-4px) scale(1.018)!important;border-color:rgba(255,255,255,.35)!important;background:rgba(255,255,255,.08)!important;}

/* HERO */
.dgs-hero{min-height:100vh;display:flex;align-items:center;padding:100px 0 80px;background:transparent!important;}
.dgs-hero:before{
  content:"";
  position:absolute;
  inset:0;
  background:
    radial-gradient(circle at 12% 20%,rgba(234,63,139,.10),transparent 30%),
    radial-gradient(circle at 82% 14%,rgba(114,193,216,.08),transparent 28%),
    linear-gradient(180deg,rgba(0,0,0,.32),rgba(0,0,0,.04))!important;
  pointer-events:none;
}
.dgs-hero-grid{display:grid;grid-template-columns:minmax(0,1.08fr) minmax(360px,.92fr);gap:clamp(36px,4.5vw,72px);align-items:center;width:100%;}
.dgs-hero h1{
  font-size:clamp(3rem,6.4vw,6.8rem)!important;
  font-weight:200!important;
  line-height:1.02!important;
  letter-spacing:-.045em!important;
  margin:0 0 28px!important;
  color:#fff!important;
}
.dgs-hero h1 span{display:block;max-width:100%;overflow-wrap:anywhere;}
.dgs-hero-copy{max-width:none;width:100%;text-align:left;}
.dgs-hero-copy .dgs-copy{max-width:900px;}
.dgs-hero-panel{align-self:center;}
.dgs-hero-proof{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:34px;max-width:900px;}
.dgs-proof-card{
  background:rgba(255,255,255,.035)!important;
  border:1px solid rgba(255,255,255,.10)!important;
  border-radius:18px!important;
  padding:18px!important;
  backdrop-filter:blur(12px)!important;
  transition:.35s ease!important;
  will-change:transform,box-shadow,border-color!important;
}
.dgs-proof-card:hover{transform:translateY(-6px) scale(1.02)!important;border-color:rgba(234,63,139,.34)!important;background:rgba(255,255,255,.06)!important;box-shadow:0 22px 58px rgba(0,0,0,.34)!important;}
.dgs-proof-card strong{display:block;font-size:clamp(1.3rem,2.4vw,2rem);line-height:1;font-weight:500;color:#fff;margin-bottom:8px;}
.dgs-proof-card span{display:block;color:var(--dgs-soft);font-size:.83rem;line-height:1.5;}
.dgs-hero-panel{
  background:linear-gradient(145deg,rgba(255,255,255,.08),rgba(255,255,255,.025))!important;
  border:1px solid rgba(255,255,255,.13)!important;
  border-radius:30px!important;
  padding:clamp(24px,3vw,36px)!important;
  box-shadow:0 28px 90px rgba(0,0,0,.35)!important;
  backdrop-filter:blur(16px)!important;
  animation:dgsFloat 8s ease-in-out infinite!important;
  transition:.35s ease!important;
  will-change:transform,box-shadow,border-color!important;
}
.dgs-hero-panel:hover{transform:translateY(-12px) scale(1.012)!important;border-color:rgba(255,255,255,.22)!important;box-shadow:0 34px 100px rgba(0,0,0,.48),0 0 50px rgba(114,193,216,.10)!important;}
.dgs-hero-panel h2{font-size:clamp(1.6rem,3vw,2.6rem);font-weight:260;line-height:1.15;letter-spacing:-.035em;margin:0 0 18px;color:#fff;}
.dgs-hero-list{display:grid;gap:12px;margin:26px 0 0;}
.dgs-hero-list div{display:flex;gap:12px;align-items:flex-start;color:var(--dgs-muted);font-size:.95rem;}
.dgs-hero-list b{width:24px;height:24px;border-radius:50%;background:linear-gradient(135deg,var(--dgs-pink),var(--dgs-orange));display:flex;align-items:center;justify-content:center;flex:0 0 auto;color:#fff;font-size:.72rem;}
.dgs-scroll{position:absolute;left:40px;bottom:50px;width:1px;height:82px;background:linear-gradient(180deg,transparent,rgba(255,255,255,.35),transparent);}
.dgs-scroll span{display:block;width:1px;height:22px;background:linear-gradient(180deg,var(--dgs-pink),var(--dgs-orange));animation:dgsDrop 2s ease infinite;}

/* LOGOS */
.dgs-logo-strip{padding:42px 0;border-top:1px solid var(--dgs-line);border-bottom:1px solid var(--dgs-line);background:rgba(0,0,0,.18)!important;backdrop-filter:blur(8px)!important;}
.dgs-logo-row{display:grid;grid-template-columns:repeat(6,1fr);gap:12px;}
.dgs-logo-chip{height:76px;border-radius:16px;border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.04);display:flex;align-items:center;justify-content:center;padding:14px;transition:.35s ease;will-change:transform,box-shadow,border-color;}
.dgs-logo-chip:hover{transform:translateY(-6px) scale(1.035)!important;border-color:rgba(234,63,139,.42);box-shadow:0 18px 50px rgba(0,0,0,.3);}
.dgs-logo-chip img{max-height:44px;max-width:100%;object-fit:contain;filter:brightness(1.05);}

/* CARDS */
.dgs-card{
  background:rgba(255,255,255,.035)!important;
  border:1px solid rgba(255,255,255,.1)!important;
  border-radius:22px!important;
  padding:clamp(24px,3vw,36px)!important;
  backdrop-filter:blur(14px)!important;
  transition:.35s ease!important;
  position:relative!important;
  overflow:hidden!important;
  will-change:transform,box-shadow,border-color!important;
}
.dgs-card:before{content:"";position:absolute;left:0;top:0;width:100%;height:2px;background:linear-gradient(90deg,var(--dgs-pink),var(--dgs-orange),transparent);transform:scaleX(0);transform-origin:left;transition:.5s ease;}
.dgs-card:hover{transform:translateY(-10px) scale(1.015)!important;border-color:rgba(255,255,255,.2)!important;background:rgba(255,255,255,.055)!important;box-shadow:0 28px 90px rgba(0,0,0,.42),0 0 42px rgba(234,63,139,.10)!important;}
.dgs-card:hover:before{transform:scaleX(1);}
.dgs-card small{display:block;font-size:.72rem;letter-spacing:3px;text-transform:uppercase;color:var(--dgs-soft);margin-bottom:18px;}
.dgs-card h3{font-size:clamp(1.35rem,2.5vw,2.15rem);font-weight:280;letter-spacing:-.03em;line-height:1.18;color:#fff;margin:0 0 14px;}
.dgs-card p{font-size:.98rem;font-weight:300;color:var(--dgs-muted);line-height:1.78;margin:0;}
.dgs-services-grid{grid-template-columns:repeat(3,1fr);}

/* DIFFERENTIATOR COMPARISON */
.dgs-comparison-grid{display:grid;grid-template-columns:.92fr 1.08fr;border:1px solid rgba(255,255,255,.11);border-radius:30px;overflow:hidden;background:rgba(0,0,0,.16)!important;backdrop-filter:blur(12px);box-shadow:0 30px 100px rgba(0,0,0,.28);}
.dgs-comparison-col{padding:clamp(24px,3vw,44px);position:relative;}
.dgs-comparison-col:first-child{border-right:1px solid rgba(255,255,255,.10);background:rgba(255,255,255,.025)!important;opacity:.72;}
.dgs-comparison-col:first-child h3,.dgs-comparison-col:first-child .dgs-comparison-list div{color:rgba(255,255,255,.58)!important;}
.dgs-comparison-col:nth-child(2){background:radial-gradient(circle at 18% 12%,rgba(234,63,139,.20),transparent 34%),radial-gradient(circle at 86% 20%,rgba(255,174,51,.12),transparent 34%),linear-gradient(145deg,rgba(255,255,255,.085),rgba(255,255,255,.035))!important;border-left:1px solid rgba(234,63,139,.28);box-shadow:inset 0 0 0 1px rgba(255,255,255,.08);}
.dgs-comparison-col:nth-child(2):before{content:"D’GENIUS ADVANTAGE";display:inline-flex;align-items:center;margin-bottom:18px;padding:8px 14px;border-radius:999px;background:linear-gradient(135deg,rgba(234,63,139,.20),rgba(255,174,51,.14));border:1px solid rgba(234,63,139,.34);color:#fff;font-size:.68rem;letter-spacing:2px;font-weight:500;}
.dgs-comparison-col h3{font-size:clamp(1.45rem,2.8vw,2.4rem);font-weight:280;line-height:1.15;letter-spacing:-.035em;margin:0 0 22px;color:#fff;}
.dgs-comparison-list{display:grid;gap:14px;}
.dgs-comparison-list div{padding:16px 18px;border-radius:15px;border:1px solid rgba(255,255,255,.09);background:rgba(255,255,255,.035);color:var(--dgs-muted);font-size:.95rem;transition:.32s ease;will-change:transform,box-shadow,border-color;}
.dgs-comparison-list div:hover{transform:translateX(8px);border-color:rgba(255,255,255,.24);background:rgba(255,255,255,.06);}
.dgs-comparison-list .good{border-color:rgba(234,63,139,.32)!important;background:linear-gradient(135deg,rgba(234,63,139,.16),rgba(255,174,51,.08))!important;color:rgba(255,255,255,.92)!important;box-shadow:0 16px 42px rgba(234,63,139,.08);}
.dgs-comparison-list .good:hover{transform:translateX(12px) scale(1.015);border-color:rgba(255,174,51,.48)!important;box-shadow:0 20px 58px rgba(0,0,0,.28),0 0 34px rgba(234,63,139,.16);}

/* PORTFOLIO */
.portfolio-filters{display:flex;gap:clamp(15px,3vw,34px);margin-bottom:40px;overflow-x:auto;scrollbar-width:thin;scrollbar-color:rgba(255,255,255,.32) transparent;-webkit-overflow-scrolling:touch;}
.portfolio-filter-tab{font-size:clamp(.7rem,1.5vw,.8rem);font-weight:300;letter-spacing:clamp(1.5px,.4vw,2.5px);color:rgba(255,255,255,.52)!important;text-transform:uppercase;white-space:nowrap;padding-bottom:12px;position:relative;display:inline-block;cursor:pointer;transition:.2s ease;}
.portfolio-filter-tab.active{color:#fff!important;}
.portfolio-filter-tab span{position:absolute;left:0;bottom:0;width:100%;height:1px;background:linear-gradient(90deg,var(--dgs-pink),var(--dgs-orange));opacity:0;}
.portfolio-filter-tab.active span{opacity:1;}
.content-view{display:none;opacity:0;transition:.35s ease;}
.content-view.active-view{display:block;opacity:1;}
#portfolio-gallery,#mascot-gallery,#festival-gallery,#mythological-gallery,#product-gallery,#jewellery-gallery,#concept-gallery{columns:4 260px;column-gap:12px;}
#tvc-gallery{columns:2 420px;column-gap:12px;}

/* AI AVATAR CATEGORY: FORCE SAME 4-VIDEO ROW LAYOUT ON DESKTOP */
#mythological-gallery{
  columns:auto!important;
  column-gap:0!important;
  display:grid!important;
  grid-template-columns:repeat(4,minmax(0,1fr))!important;
  gap:12px!important;
}
#mythological-gallery .case-study-item{
  width:100%!important;
  margin:0!important;
  break-inside:auto!important;
}
#mythological-gallery .case-study-item:not(.wide-item),
#mythological-gallery .case-study-item:not(.wide-item) .video-wrapper{
  aspect-ratio:9/16!important;
}
@media (max-width:1100px){
  #mythological-gallery{grid-template-columns:repeat(2,minmax(0,1fr))!important;}
}
@media (max-width:760px){
  #mythological-gallery{grid-template-columns:1fr!important;columns:auto!important;}
}

.gallery-item,.case-study-item{display:block;width:100%;margin:0 0 12px;break-inside:avoid;position:relative;background:#050505;border:1px solid rgba(255,255,255,.08);overflow:hidden;cursor:pointer;border-radius:10px;transition:.25s ease;contain:layout paint style;}
.gallery-item:not(.wide-item),.case-study-item:not(.wide-item){aspect-ratio:9/16;}
.gallery-item.wide-item,.case-study-item.wide-item,.case-study-item.wide-item .video-wrapper{aspect-ratio:16/9;}
.gallery-item:hover,.case-study-item:hover{border-color:rgba(255,107,157,.55);box-shadow:0 10px 36px rgba(255,107,157,.28);transform:translateY(-5px) scale(1.01);}
.video-wrapper{position:relative;width:100%;overflow:hidden;background:#000;aspect-ratio:9/16;}
.thumb-img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center top;background:#0a0a0a;transition:.3s ease;}
.thumb-video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center top;background:#0a0a0a;transition:.3s ease;opacity:0;filter:brightness(1.08) contrast(1.04);}
.thumb-video.is-ready{opacity:1;}
.thumb-fallback{position:absolute;inset:0;background:radial-gradient(circle at 25% 20%,rgba(255,107,157,.32),transparent 32%),radial-gradient(circle at 75% 30%,rgba(255,168,52,.22),transparent 34%),linear-gradient(135deg,#070707,#111 48%,#050505);}
.play-btn-overlay{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;z-index:3;pointer-events:none;opacity:0;transition:.25s ease;}
.gallery-item:hover .play-btn-overlay,.case-study-item:hover .play-btn-overlay{opacity:1;}
.play-btn-circle{width:56px;height:56px;border-radius:50%;background:rgba(0,0,0,.58);border:2px solid rgba(255,255,255,.74);backdrop-filter:blur(6px);display:flex;align-items:center;justify-content:center;box-shadow:0 12px 34px rgba(0,0,0,.45);}
.play-btn-circle svg{width:20px;height:20px;margin-left:3px;fill:#fff;}
.video-overlay{position:absolute;bottom:0;left:0;right:0;padding:14px;background:linear-gradient(180deg,transparent,rgba(0,0,0,.94));z-index:2;pointer-events:none;}

/* LIGHTBOX */
.portfolio-lightbox{position:fixed!important;inset:0!important;width:100vw!important;height:100dvh!important;min-height:100vh!important;background:#000!important;z-index:2147483647!important;display:none;opacity:0;align-items:center!important;justify-content:center!important;padding:34px!important;transition:opacity .24s ease!important;overflow:hidden!important;isolation:isolate!important;}
.portfolio-lightbox:before{content:""!important;position:absolute!important;inset:0!important;background:#000!important;z-index:-1!important;pointer-events:none!important;}
.portfolio-lightbox.is-open{display:flex!important;opacity:1!important;}
.portfolio-lightbox-content{width:min(92vw,1280px)!important;height:calc(100dvh - 110px)!important;max-height:calc(100vh - 110px)!important;display:flex!important;align-items:center!important;justify-content:center!important;position:relative!important;margin:auto!important;overflow:hidden!important;}
#lightbox-player{display:block!important;width:auto!important;height:auto!important;max-width:100%!important;max-height:100%!important;object-fit:contain!important;border-radius:12px!important;background:#000!important;box-shadow:0 28px 80px rgba(0,0,0,.9)!important;margin:auto!important;}
#lightbox-player.is-landscape{width:min(92vw,1280px)!important;height:auto!important;max-height:calc(100vh - 140px)!important;}
#lightbox-player.is-portrait{width:auto!important;height:min(84dvh,920px)!important;max-height:calc(100vh - 110px)!important;max-width:min(92vw,620px)!important;}
.portfolio-lightbox-btn,.dgs-ai-page .portfolio-lightbox-btn{position:absolute!important;z-index:2147483647!important;border:1px solid rgba(255,255,255,.28)!important;background:#111!important;background-image:none!important;color:#fff!important;-webkit-text-fill-color:#fff!important;cursor:pointer!important;display:flex!important;align-items:center!important;justify-content:center!important;line-height:1!important;padding:0!important;margin:0!important;box-shadow:0 8px 24px rgba(0,0,0,.55)!important;backdrop-filter:blur(8px)!important;transition:.2s ease!important;text-shadow:none!important;}
.portfolio-lightbox-btn:before,.portfolio-lightbox-btn:after,.dgs-ai-page .portfolio-lightbox-btn:before,.dgs-ai-page .portfolio-lightbox-btn:after{display:none!important;content:none!important;background:none!important;}
.portfolio-lightbox-btn:hover,.portfolio-lightbox-btn:focus{background:#1c1c1c!important;background-image:none!important;border-color:rgba(255,255,255,.55)!important;color:#fff!important;transform:translateY(-50%) scale(1.05)!important;outline:none!important;}
.portfolio-lightbox-close:hover,.portfolio-lightbox-close:focus{transform:scale(1.05)!important;}
.portfolio-lightbox-close{top:28px!important;right:28px!important;width:54px!important;height:54px!important;border-radius:999px!important;font-size:30px!important;font-weight:300!important;}
.portfolio-lightbox-arrow{top:50%!important;width:54px!important;height:54px!important;border-radius:999px!important;font-size:42px!important;font-weight:300!important;transform:translateY(-50%)!important;}
.portfolio-lightbox-prev{left:28px!important;}
.portfolio-lightbox-next{right:28px!important;}
body.lightbox-open header.elementor-location-header,body.lightbox-open header.elementor-sticky,body.lightbox-open header.elementor-sticky--effects{opacity:0!important;visibility:hidden!important;pointer-events:none!important;transition:.25s ease;}
body.lightbox-open .dgs-ai-page > section{visibility:hidden!important;}
body.lightbox-open .dgs-ai-page #portfolio{visibility:visible!important;}
body.lightbox-open .dgs-ai-page #portfolio > .dgs-wrap > :not(.portfolio-lightbox){visibility:hidden!important;}
body.lightbox-open .dgs-ai-page .portfolio-lightbox,body.lightbox-open .dgs-ai-page .portfolio-lightbox *{visibility:visible!important;}

/* PROCESS */
.dgs-process{position:relative;}
.dgs-process-line{position:absolute;left:40px;top:40px;bottom:40px;width:1px;background:linear-gradient(180deg,var(--dgs-pink),var(--dgs-orange),var(--dgs-blue),var(--dgs-purple));opacity:.35;}
.process-step{position:relative;margin-bottom:78px;padding-left:118px;opacity:0;transform:translateY(30px);transition:.8s ease;}
.process-step:last-child{margin-bottom:0;}
.process-num{position:absolute;left:0;top:0;width:80px;height:80px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,var(--dgs-pink),var(--dgs-orange));box-shadow:0 10px 40px rgba(234,63,139,.3);z-index:2;}
.process-num span{font-size:1.7rem;font-weight:230;color:#fff;}
.process-card{background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.1);border-radius:18px;padding:34px;backdrop-filter:blur(12px);transition:.35s ease;}
.process-card:hover{transform:translateY(-6px) scale(1.01);background:rgba(255,255,255,.055);border-color:rgba(255,255,255,.18);box-shadow:0 22px 60px rgba(0,0,0,.28);}
.process-card h3{font-size:clamp(1.4rem,2.8vw,2.4rem);font-weight:260;letter-spacing:-.035em;line-height:1.16;margin:0 0 12px;color:#fff;}
.process-points{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:24px;}
.process-points span{font-size:.9rem;color:var(--dgs-soft);display:flex;gap:10px;}
.process-points span:before{content:"";width:6px;height:6px;border-radius:50%;background:linear-gradient(135deg,var(--dgs-pink),var(--dgs-orange));margin-top:8px;flex:0 0 auto;}

/* STATS, TESTIMONIALS, FAQ, FORM */
.dgs-stats-grid{grid-template-columns:repeat(4,1fr);}
.dgs-stat{text-align:center;background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.09);border-radius:20px;padding:36px 24px;transition:.35s ease;}
.dgs-stat:hover{transform:translateY(-8px) scale(1.015);border-color:rgba(234,63,139,.28);background:rgba(255,255,255,.05);}
.dgs-stat strong{display:block;font-size:clamp(2.8rem,5vw,4.5rem);font-weight:200;line-height:1;margin-bottom:12px;}
.dgs-stat span{display:block;color:var(--dgs-muted);font-size:.95rem;}
.testimonials-grid{grid-template-columns:repeat(3,1fr);}
.testimonial-card{background:linear-gradient(135deg,rgba(234,63,139,.05),rgba(255,174,51,.04));border:1px solid rgba(255,255,255,.09);border-radius:20px;padding:34px;transition:.35s ease;}
.testimonial-card:hover{transform:translateY(-8px) scale(1.012);border-color:rgba(255,255,255,.18);box-shadow:0 20px 60px rgba(0,0,0,.35);}
.stars{color:var(--dgs-orange);letter-spacing:3px;margin-bottom:20px;}
.faq-container{max-width:940px;margin:0 auto;}
.faq-item{border-bottom:1px solid rgba(255,255,255,.1);position:relative;}
.faq-item:before{content:"";position:absolute;left:0;top:0;width:2px;height:0;background:linear-gradient(180deg,var(--dgs-pink),var(--dgs-orange),var(--dgs-blue));transition:.35s ease;}
.faq-item.active:before{height:100%;}
.faq-q{width:100%;padding:25px 50px 25px 15px;background:rgba(255,255,255,.025)!important;background-image:none!important;background-color:rgba(255,255,255,.025)!important;border:none!important;color:#fff!important;-webkit-text-fill-color:#fff!important;text-align:left;font-size:clamp(1rem,2vw,1.22rem);font-weight:300;font-family:'Inter',sans-serif;cursor:pointer;position:relative;box-shadow:none!important;}
.dgs-ai-page #faq-section-ai-video .faq-q,.dgs-ai-page #faq-section-ai-video button.faq-q,.dgs-ai-page .faq-container button,.dgs-ai-page .faq-item button{background:rgba(255,255,255,.025)!important;background-image:none!important;background-color:rgba(255,255,255,.025)!important;color:#fff!important;-webkit-text-fill-color:#fff!important;border:0!important;box-shadow:none!important;text-shadow:none!important;}
.dgs-ai-page #faq-section-ai-video .faq-q:hover,.dgs-ai-page #faq-section-ai-video .faq-q:focus,.dgs-ai-page #faq-section-ai-video .faq-q:active,.dgs-ai-page .faq-item.active .faq-q{background:rgba(255,255,255,.055)!important;background-image:none!important;background-color:rgba(255,255,255,.055)!important;color:#fff!important;-webkit-text-fill-color:#fff!important;outline:none!important;}
.dgs-ai-page #faq-section-ai-video .faq-q:before,.dgs-ai-page #faq-section-ai-video .faq-q:after,.dgs-ai-page .faq-container button:before,.dgs-ai-page .faq-container button:after{display:none!important;content:none!important;background:none!important;background-image:none!important;}
.faq-q i{position:absolute;right:0;top:50%;transform:translateY(-50%);font-style:normal;color:rgba(255,255,255,.55);font-size:1.25rem;transition:.3s ease;}
.faq-item.active .faq-q i{transform:translateY(-50%) rotate(45deg);color:var(--dgs-pink);}
.faq-a{max-height:0;overflow:hidden;transition:.4s ease;}
.faq-a div{padding:0 15px 28px;color:var(--dgs-muted);font-size:.96rem;font-weight:300;line-height:1.85;}
.cta-box{max-width:900px;margin:0 auto;background:rgba(255,255,255,.035);border:1px solid rgba(255,255,255,.1);border-radius:28px;padding:clamp(30px,6vw,58px);backdrop-filter:blur(14px);position:relative;overflow:hidden;}
.cta-box:before{content:"";position:absolute;top:0;left:0;width:100%;height:1px;background:linear-gradient(90deg,transparent,var(--dgs-pink),var(--dgs-orange),var(--dgs-blue),transparent);}

/* FORM WRAPPER: works for Forminator and Fluent if either is used */
.dgs-form-wrapper .forminator-ui,.dgs-form-wrapper .fluentform,.dgs-form-wrapper form{background:transparent!important;background-image:none!important;}
.dgs-form-wrapper input[type="text"],.dgs-form-wrapper input[type="email"],.dgs-form-wrapper input[type="tel"],.dgs-form-wrapper input[type="number"],.dgs-form-wrapper input[type="url"],.dgs-form-wrapper textarea,.dgs-form-wrapper select,.dgs-form-wrapper .forminator-input,.dgs-form-wrapper .forminator-textarea,.dgs-form-wrapper .forminator-select,.dgs-form-wrapper .ff-el-form-control{display:block!important;width:100%!important;box-sizing:border-box!important;background:rgba(255,255,255,.04)!important;border:1px solid rgba(255,255,255,.11)!important;border-radius:12px!important;color:#fff!important;font-family:'Inter',sans-serif!important;font-weight:300!important;font-size:.95rem!important;padding:15px 18px!important;transition:.3s ease!important;}
.dgs-form-wrapper input:focus,.dgs-form-wrapper textarea:focus,.dgs-form-wrapper select:focus{background:rgba(255,255,255,.06)!important;border-color:rgba(234,63,139,.5)!important;outline:none!important;box-shadow:0 0 0 3px rgba(234,63,139,.1)!important;}
.dgs-form-wrapper label,.dgs-form-wrapper .forminator-label,.dgs-form-wrapper .ff-el-input--label label,.dgs-form-wrapper .ff_label_text{color:rgba(255,255,255,.82)!important;font-family:'Inter',sans-serif!important;font-weight:400!important;font-size:.86rem!important;letter-spacing:.4px!important;background:transparent!important;}
.dgs-form-wrapper select option{background:#181818!important;color:#fff!important;}
.dgs-form-wrapper .forminator-button-submit,.dgs-form-wrapper .ff-btn-submit,.dgs-form-wrapper button[type="submit"]{background:linear-gradient(135deg,var(--dgs-pink),var(--dgs-orange))!important;color:#fff!important;font-family:'Inter',sans-serif!important;font-weight:500!important;font-size:.95rem!important;letter-spacing:1px!important;text-transform:uppercase!important;padding:16px 44px!important;border-radius:50px!important;cursor:pointer!important;border:none!important;box-shadow:0 10px 30px rgba(234,63,139,.3)!important;transition:.3s ease!important;}
.dgs-form-wrapper .forminator-button-submit:hover,.dgs-form-wrapper .ff-btn-submit:hover,.dgs-form-wrapper button[type="submit"]:hover{transform:translateY(-3px)!important;box-shadow:0 15px 45px rgba(253,92,98,.38)!important;}

/* SIMPLE TEXT PHONE FIELD ONLY: no country dropdown */
.dgs-form-wrapper input[placeholder="Mobile Number"],
.dgs-form-wrapper input[name*="phone" i],
.dgs-form-wrapper input[name*="mobile" i]{
  padding-left:18px!important;
  background:rgba(255,255,255,.04)!important;
  background-image:none!important;
  color:#fff!important;
  -webkit-text-fill-color:#fff!important;
  caret-color:#fff!important;
  border:1px solid rgba(255,255,255,.16)!important;
  border-radius:12px!important;
  box-shadow:none!important;
}

.dgs-form-wrapper input[placeholder="Mobile Number"]::placeholder,
.dgs-form-wrapper input[name*="phone" i]::placeholder,
.dgs-form-wrapper input[name*="mobile" i]::placeholder{
  color:rgba(255,255,255,.48)!important;
  -webkit-text-fill-color:rgba(255,255,255,.48)!important;
  opacity:1!important;
}

/* =========================
   CTA BUTTON OVERRIDE
========================= */
.dgs-form-wrapper .forminator-button-submit,
.dgs-form-wrapper .ff-btn-submit,
.dgs-form-wrapper button[type="submit"],
.dgs-form-wrapper input[type="submit"]{
  background: #FD5C62 !important;
  background-image: none !important;
  border: 0 !important;
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  border-radius: 999px !important;
  padding: 16px 30px !important;
  font-weight: 700 !important;
  letter-spacing: .03em !important;
  box-shadow: 0 14px 34px rgba(253,92,98,.28) !important;
  transition: transform .28s ease, box-shadow .28s ease, background .28s ease !important;
}

.dgs-form-wrapper .forminator-button-submit:hover,
.dgs-form-wrapper .ff-btn-submit:hover,
.dgs-form-wrapper button[type="submit"]:hover,
.dgs-form-wrapper input[type="submit"]:hover{
  background: #f54c53 !important;
  background-image: none !important;
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  transform: translateY(-3px) !important;
  box-shadow: 0 18px 42px rgba(253,92,98,.38) !important;
}

/* =========================
   GENERAL FORM FIELD CLEANUP
========================= */
.dgs-form-wrapper input,
.dgs-form-wrapper textarea,
.dgs-form-wrapper select,
.dgs-form-wrapper .ff-el-form-control{
  background: rgba(255,255,255,.04) !important;
  background-image: none !important;
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  border: 1px solid rgba(255,255,255,.16) !important;
  box-shadow: none !important;
}

.dgs-form-wrapper input::placeholder,
.dgs-form-wrapper textarea::placeholder{
  color: rgba(255,255,255,.48) !important;
  -webkit-text-fill-color: rgba(255,255,255,.48) !important;
}

@media (max-width:1100px){
  .dgs-hero-grid,.dgs-comparison-grid{grid-template-columns:1fr;}
  .dgs-services-grid,.testimonials-grid{grid-template-columns:repeat(2,1fr);}
  .dgs-stats-grid{grid-template-columns:repeat(2,1fr);}
  .dgs-logo-row{grid-template-columns:repeat(3,1fr);}
  .dgs-comparison-col:first-child{border-right:0;border-bottom:1px solid rgba(255,255,255,.1);}
}
@media (max-width:760px){
  .dgs-wrap{width:100%!important;max-width:none!important;padding-left:14px!important;padding-right:14px!important;}
  .dgs-section{padding:76px 0;}
  .dgs-section-tight{padding:62px 0;}
  .dgs-hero{padding:70px 0 50px;}
  .dgs-hero h1{font-size:clamp(2.55rem,12vw,3.5rem)!important;line-height:1.04!important;letter-spacing:-.035em!important;}
  .dgs-hero-copy,.dgs-hero-panel{text-align:left!important;}
  .dgs-hero-grid{gap:34px!important;}
  .dgs-hero-proof{grid-template-columns:1fr!important;max-width:none!important;}
  .dgs-btn-row,.dgs-btn{width:100%;}
  .dgs-hero-proof,.dgs-services-grid,.testimonials-grid,.dgs-stats-grid,.process-points{grid-template-columns:1fr;}
  .dgs-logo-row{grid-template-columns:repeat(2,1fr);}
  #portfolio-gallery,#mascot-gallery,#festival-gallery,#mythological-gallery,#product-gallery,#jewellery-gallery,#concept-gallery,#tvc-gallery{columns:1!important;}
  .process-step{padding-left:82px;margin-bottom:48px;}
  .process-num{width:58px;height:58px;}
  .process-num span{font-size:1.25rem;}
  .dgs-process-line{left:29px;}
  .process-card{padding:24px;}
  .dgs-scroll{display:none;}
  .portfolio-lightbox{padding:72px 12px 68px!important;}
  .portfolio-lightbox-content{width:100%!important;height:calc(100vh - 140px)!important;}
  .portfolio-lightbox-close{top:14px!important;right:14px!important;width:42px!important;height:42px!important;}
  .portfolio-lightbox-arrow{top:auto!important;bottom:16px!important;width:44px!important;height:44px!important;transform:none!important;}
  .portfolio-lightbox-arrow:hover,.portfolio-lightbox-arrow:focus{transform:scale(1.05)!important;}
  .portfolio-lightbox-prev{left:calc(50% - 58px)!important;}
  .portfolio-lightbox-next{right:calc(50% - 58px)!important;}
}

/* Remove TARGET KEYWORD text from the cards */
.dgs-card small{
  display:none!important;
}

/* Keep heading spacing clean after removing label */
.dgs-card h3{
  margin-top:0!important;
}
/* =========================================
   DARK FORM + CHROME AUTOFILL FIX
========================================= */
.dgs-form-wrapper input[type="text"],
.dgs-form-wrapper input[type="email"],
.dgs-form-wrapper input[type="tel"],
.dgs-form-wrapper input[type="number"],
.dgs-form-wrapper input[type="url"],
.dgs-form-wrapper input[type="password"],
.dgs-form-wrapper textarea,
.dgs-form-wrapper select,
.dgs-form-wrapper .ff-el-form-control,
.dgs-form-wrapper .forminator-input,
.dgs-form-wrapper .forminator-textarea,
.dgs-form-wrapper .forminator-select{
  display:block!important;
  width:100%!important;
  min-height:48px!important;
  padding:14px 16px!important;
  background:#161616!important;
  background-color:#161616!important;
  background-image:none!important;
  color:#fff!important;
  -webkit-text-fill-color:#fff!important;
  border:1px solid rgba(255,255,255,.16)!important;
  border-radius:12px!important;
  font-family:'Inter',sans-serif!important;
  font-size:.95rem!important;
  font-weight:300!important;
  line-height:1.4!important;
  box-shadow:none!important;
  caret-color:#fff!important;
}

/* Chrome, Edge and Safari autofill */
.dgs-form-wrapper input:-webkit-autofill,
.dgs-form-wrapper input:-webkit-autofill:hover,
.dgs-form-wrapper input:-webkit-autofill:focus,
.dgs-form-wrapper input:-webkit-autofill:active,
.dgs-form-wrapper textarea:-webkit-autofill,
.dgs-form-wrapper textarea:-webkit-autofill:hover,
.dgs-form-wrapper textarea:-webkit-autofill:focus,
.dgs-form-wrapper textarea:-webkit-autofill:active,
.dgs-form-wrapper select:-webkit-autofill,
.dgs-form-wrapper select:-webkit-autofill:hover,
.dgs-form-wrapper select:-webkit-autofill:focus,
.dgs-form-wrapper select:-webkit-autofill:active{
  -webkit-text-fill-color:#fff!important;
  caret-color:#fff!important;
  border:1px solid rgba(255,255,255,.16)!important;
  -webkit-box-shadow:0 0 0 1000px #161616 inset!important;
  box-shadow:0 0 0 1000px #161616 inset!important;
  transition:background-color 9999s ease-out 0s!important;
}

/* Firefox autofill */
.dgs-form-wrapper input:autofill,
.dgs-form-wrapper textarea:autofill,
.dgs-form-wrapper select:autofill{
  background:#161616!important;
  color:#fff!important;
  -webkit-text-fill-color:#fff!important;
  box-shadow:0 0 0 1000px #161616 inset!important;
}

/* Focus state */
.dgs-form-wrapper input:focus,
.dgs-form-wrapper textarea:focus,
